    const n = big ? 50000 : r.int(1, 8), m = big ? 50000 : r.int(0, Math.min(10, n * (n - 1) / 2));
    const perm = r.shuffle([...Array(n).keys()]), seen = new Set(), deps = [];
    for (let t = 0; t < m * 3 && deps.length < m && n > 1; t++) {
      let i = r.int(0, n - 1), j = r.int(0, n - 1);
      if (i === j) continue;
      if (i > j) [i, j] = [j, i];
      if (big && j - i > 50) j = i + r.int(1, 50);
      if (j >= n) continue;
      const k = perm[i] * n + perm[j];
      if (seen.has(k)) continue;
      seen.add(k); deps.push([perm[i], perm[j]]);
    }
    return [n, deps, r.arr(n, 1, big ? 10000 : 9)];
  }

