function fastestFinish(n: number, deps: number[][], time: number[]): number {
  const finish = [...time];
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of deps)
      if (finish[a] + time[b] > finish[b]) { finish[b] = finish[a] + time[b]; changed = true; }
  }
  return Math.max(...finish);
}

