function fastestFinish(n: number, deps: number[][], time: number[]): number {
  const out: number[][] = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0), start = new Array(n).fill(0);
  for (const [a, b] of deps) { out[a].push(b); indeg[b]++; }
  const queue: number[] = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
  let best = 0;
  for (let h = 0; h < queue.length; h++) {
    const u = queue[h], finish = start[u] + time[u];
    best = Math.max(best, finish);
    for (const v of out[u]) {
      start[v] = Math.max(start[v], finish);
      if (--indeg[v] === 0) queue.push(v);
    }
  }
  return best;
}

